use std::{fs, hint::black_box, path::Path};
use gigastt_core::inference::audio::{decode_audio_bytes, replay_pilot_packets};

fn cpu_ticks() -> u64 {
    let stat = fs::read_to_string("/proc/self/stat").unwrap();
    let mut cols = stat.rsplit_once(')').unwrap().1.split_whitespace().skip(11);
    cols.next().unwrap().parse::<u64>().unwrap() + cols.next().unwrap().parse::<u64>().unwrap()
}

fn main() {
    let args: Vec<_> = std::env::args().collect();
    let dir = Path::new(&args[1]);
    let mode = &args[2];
    let corpus: Vec<_> = (0..15).map(|i| {
        if mode == "input" {
            vec![fs::read(dir.join(format!("golos_{i:02}.opus"))).unwrap()]
        } else {
            let file = fs::read(dir.join(format!("golos_{i:02}"))).unwrap();
            let mut rem = &file[..];
            let mut packets = Vec::new();
            while !rem.is_empty() {
                let n = u32::from_be_bytes(rem[..4].try_into().unwrap()) as usize;
                packets.push(rem[4..4+n].to_vec());
                rem = &rem[4+n..];
            }
            packets
        }
    }).collect();
    let run = || {
        for clip in &corpus {
            if mode == "input" {
                black_box(decode_audio_bytes(&clip[0]).unwrap());
            } else {
                replay_pilot_packets(clip).unwrap();
            }
        }
    };
    run();
    let before = cpu_ticks();
    for _ in 0..24 { run(); }
    println!("{}", cpu_ticks()-before);
}

